mapper.delete:
delete from kb_graph_community
 where kb_id = #{kbId}
and graph_version = #{graphVersion}

delete from kb_graph_entity_community
 where kb_id = #{kbId}
and graph_version = #{graphVersion}

mapper.select:
select * from kb_graph_community
 where kb_id = #{kbId} and graph_version = #{graphVersion}
 order by level asc, community_id asc

select * from kb_graph_entity_community
 where kb_id = #{kbId} and graph_version = #{graphVersion}
 order by level asc, community_id asc, entity_key asc

select * from kb_graph_community_report
 where kb_id = #{kbId} and graph_version = #{graphVersion}
 order by level asc, community_id asc

select * from kb_graph_community_report_source
 where report_id = #{reportId}
 order by evidence_rank asc

select * from kb_graph_community_report
 where kb_id = #{kbId} and content_hash = #{contentHash}
 limit 1
